// A work interval shows only the player's present state. The next event is
// deliberately not accepted here: no person, title, source or outcome leaks.
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const value=(input,max=100)=>Math.max(0,Math.min(max,Number.isFinite(Number(input))?Math.round(Number(input)):0));
export function renderWorkGapHTMLV50({day=1,stats={},restAllowed=false,restReason='',warningHTML='',mobileWorkbarHTML='',continueChoiceHTML=''}={}){
 const mood=value(stats.mood),energy=value(stats.energy),cash=value(stats.cash,Number.MAX_SAFE_INTEGER);
 const meter=(label,current,key)=>`<div class="work-gap-stat${current<=15?' critical':current<=30?' caution':''}" data-gap-stat="${key}"><span>${label}</span><b>${current}<small>/ 100</small></b><div class="work-gap-meter" aria-hidden="true"><i style="width:${current}%"></i></div></div>`;
 return `<article class="chapter work-gap-chapter" data-work-gap tabindex="-1">${mobileWorkbarHTML}<div class="chapter-meta"><span>DAY ${String(value(day,999)).padStart(2,'0')} / 工作空檔</span><span class="tag">先喘口氣</span></div><div class="work-gap-heading"><span class="work-gap-cup" aria-hidden="true">☕</span><span class="eyebrow">A MOMENT TO YOURSELF.</span><h1 class="chapter-title">事情告一段落，<br>先看看自己。</h1><p class="chapter-body">上一件事處理完了，下一段工作還沒開始。要先安排休息、花點存款照顧自己，還是直接繼續上班？</p></div>${warningHTML}<div class="work-gap-resources" aria-label="目前身心與存款">${meter('自己心情',mood,'mood')}${meter('體力',energy,'energy')}<div class="work-gap-stat work-gap-cash" data-gap-stat="cash"><span>存款</span><b>${cash}</b><small>花在自己身上，也算有用途。</small></div></div><section class="work-gap-rest" aria-labelledby="work-gap-rest-title"><div><span class="eyebrow">YOUR TIME, YOUR MONEY.</span><h2 id="work-gap-rest-title">這段空檔，留給自己。</h2><p>${restAllowed?'打開安排再決定。這個工作回合可安排一次，選擇先不花錢也算一次。':'這段空檔已安排過休息。完成下一件工作後，才有下一次安排。'}</p></div><button type="button" class="secondary" data-action="break"${restAllowed?'':' disabled aria-describedby="gap-rest-reason"'}>存款怎麼花 <span aria-hidden="true">↗</span></button>${!restAllowed?`<p class="work-gap-rest-reason" id="gap-rest-reason">${esc(restReason||'完成下一件工作後，再安排休息。')}</p>`:''}</section><div class="work-gap-continue"><p>準備好了，再處理下一件事。</p>${continueChoiceHTML}</div><p class="work-gap-footnote">休息、飯局與職涯安排不會另外多算一個工作回合。</p></article>`;
}
